CREATE DATABASE IF NOT EXISTS controle_gastos CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE controle_gastos;
CREATE TABLE IF NOT EXISTS usuarios (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,senha VARCHAR(255) NOT NULL,perfil ENUM('admin','usuario') NOT NULL DEFAULT 'usuario',ativo TINYINT(1) NOT NULL DEFAULT 1,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transacoes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,tipo ENUM('receita','despesa') NOT NULL,data_lancamento DATE NOT NULL,descricao VARCHAR(255) NOT NULL,categoria VARCHAR(100) NOT NULL,valor DECIMAL(12,2) NOT NULL,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,INDEX(data_lancamento),INDEX(tipo));
CREATE TABLE IF NOT EXISTS operacionais (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,data_lancamento DATE NOT NULL,descricao VARCHAR(255) NOT NULL,categoria VARCHAR(100) NOT NULL,valor DECIMAL(12,2) NOT NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS investimentos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,ativo VARCHAR(150) NOT NULL,data_aporte DATE NOT NULL,valor DECIMAL(12,2) NOT NULL,rentabilidade DECIMAL(8,2) DEFAULT 0,observacoes TEXT,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS configuracoes (chave VARCHAR(80) PRIMARY KEY,valor TEXT NOT NULL);
INSERT INTO configuracoes(chave,valor) VALUES ('moeda','BRL') ON DUPLICATE KEY UPDATE chave=chave;